{
  "title": "History and Publication Changes of Science Fantasy Magazine",
  "nodes": [
    {
      "name": "Science Fantasy",
      "type": "Work",
      "isolated_context": "Science Fantasy was a British fantasy and science fiction magazine. It appeared under the titles Impulse and SF Impulse. It ceased publication the following year due to financial pressure on Roberts & Vinter after their printer went bankrupt."
    },
    {
      "name": "Impulse",
      "type": "Work",
      "isolated_context": "Impulse was a title under which Science Fantasy appeared. Changing the title to Impulse in early 1966 led to confusion with distributors and caused sales to fall, although the magazine remained profitable."
    },
    {
      "name": "SF Impulse",
      "type": "Work",
      "isolated_context": "SF Impulse was a title used for the last few issues of the magazine. The change to this title occurred after the title Impulse caused confusion and sales to drop."
    },
    {
      "name": "Nova Publications",
      "type": "Organization",
      "isolated_context": "Nova Publications launched Science Fantasy in 1950 as a companion to Nova's \"New Worlds\". The company eventually went out of business in early 1964."
    },
    {
      "name": "New Worlds",
      "type": "Work",
      "isolated_context": "New Worlds was a publication associated with Nova Publications. John Carnell was the editor of this magazine."
    },
    {
      "name": "Walter Gillings",
      "type": "Person",
      "isolated_context": "Walter Gillings served as the editor for the first two issues of Science Fantasy."
    },
    {
      "name": "John Carnell",
      "type": "Person",
      "isolated_context": "John Carnell replaced Walter Gillings as editor and became the editor of New Worlds. He edited both magazines until Nova went out of business in early 1964."
    },
    {
      "name": "Roberts & Vinter",
      "type": "Organization",
      "isolated_context": "Roberts & Vinter acquired the titles and hired Kyril Bonfiglioli to edit Science Fantasy. They later came under financial pressure after their printer went bankrupt."
    },
    {
      "name": "Kyril Bonfiglioli",
      "type": "Person",
      "isolated_context": "Kyril Bonfiglioli was hired by Roberts & Vinter to edit Science Fantasy. He changed the title to Impulse in early 1966."
    },
    {
      "name": "Printer",
      "type": "Thing",
      "isolated_context": "The printer of Roberts & Vinter went bankrupt, which led to financial pressure on Roberts & Vinter and caused Science Fantasy to cease publication."
